pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // newOwner can be any address, including zero to trigger the bug
        vm.assume(newOwner != address(c)); // avoid self-transfer which might have different semantics

        // Attempt transferOwnership
        bool success;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        // If the call did not revert, the new owner must be exactly newOwner.
        // The reference ensures this via require(newOwner != address(0)), so it always holds.
        // The buggy version lacks this check, so when newOwner == address(0), the call succeeds
        // but owner() becomes address(0) != newOwner (since newOwner is zero, zero == zero would hold,
        // so we actually check: if success && newOwner == address(0) then owner() is 0 in buggy, which equals newOwner.
        // We need a property that reference satisfies but bug violates. 
        // Actually, reference reverts for newOwner == 0, so success is false, property vacuously true.
        // Bug succeeds for newOwner == 0, but then owner() becomes 0, which equals newOwner.
        // So we need a property that is always true for reference, but false for bug for some input.
        // Proper property: The transfer either reverts OR the new owner is not the zero address.
        assertTrue(!success || c.owner() != address(0));
    }
}

