pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner1, address newOwner2) public {
        vm.assume(newOwner1 != address(0));
        vm.assume(newOwner2 == address(0));

        // Step 1: transfer ownership to a non-zero address
        vm.prank(c.owner());
        c.transferOwnership(newOwner1);
        // At this point the contract (reference and buggy) correctly stores newOwner1

        // Step 2: the new owner (newOwner1) transfers ownership to address(0)
        vm.prank(newOwner1);
        bool okZero;
        try c.transferOwnership(newOwner2) { okZero = true; } catch { okZero = false; }

        if (okZero) {
            // If transfer to zero succeeded, the contract is in a broken state.
            // The invariant: owner() must be address(0) if and only if the last
            // successful transfer was to address(0). In the reference, this
            // transfer reverts, so owner() stays newOwner1. In the bug (where
            // the require is removed) it succeeds and sets owner to address(0),
            // breaking the property that a prior non-zero transfer persists.
            assertEq(c.owner(), newOwner1, "transfer to zero should not change owner away from last valid non-zero transfer");
        } else {
            // Implicit pass: reference behaviour – transfer to zero reverts, owner stays newOwner1
            assert(true);
        }
    }
}

